import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Finds the shortest path in a weighted directed graph using Dijkstra's algorithm.

    Args:
        graph (dict): Adjacency list representation of the graph.
        start (str): The starting node.
        end (str): The target node.

    Returns:
        tuple: A tuple containing the shortest distance and the path as a list of nodes.
    """
    min_heap = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while min_heap:
        current_distance, current_node = heapq.heappop(min_heap)

        if current_node == end:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous_nodes[current_node]
            path.reverse()
            return (current_distance, path)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(min_heap, (distance, neighbor))

    return (float('inf'), [])

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Finds the shortest path in a weighted directed graph using the Bellman-Ford algorithm.

    Args:
        graph (dict): Adjacency list representation of the graph.
        start (str): The starting node.
        end (str): The target node.

    Returns:
        tuple: A tuple containing the shortest distance and the path as a list of nodes.
    """
    distance = {node: float('inf') for node in graph}
    distance[start] = 0
    predecessor = {node: None for node in graph}

    # Relax edges |V| - 1 times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distance[node] + weight < distance[neighbor]:
                    distance[neighbor] = distance[node] + weight
                    predecessor[neighbor] = node

    # Check for negative-weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distance[node] + weight < distance[neighbor]:
                return (float('inf'), [])

    # Construct the shortest path
    if distance[end] == float('inf'):
        return (float('inf'), [])

    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessor[current]
    path.reverse()

    return (distance[end], path)

